const cfg = $('Load config').first().json;
const since = DateTime.now().minus({ days: cfg.kpi.lookback_days }).startOf('day').toUTC().toISO({ suppressMilliseconds: true });
return Object.entries(cfg.campaigns)
  .filter(([, c]) => c.kpi?.enabled)
  .map(([key, c]) => ({ json: { campaign_key: key, op: 'search_activities',
    payload: { subject_prefix: c.label, campaign_key: key, since } } }));

// One row per campaign per local day. Test runs excluded. Retries counted separately.
const cfg = $('Load config').first().json;
const plans = $('Plan KPI jobs').all();
const results = $input.all();
if (plans.length !== results.length) throw new Error('KPI search results are not aligned with campaigns');

const rows = [];
plans.forEach(({ json: plan }, i) => {
  const c = cfg.campaigns[plan.campaign_key];
  const k = c.kpi ?? {};
  const notConnected = new Set((k.not_connected ?? ['voicemail', 'no answer', 'failed']).map(s => s.toLowerCase()));
  const success = new Set((k.success_outcomes ?? ['booked']).map(s => s.toLowerCase()));
  const days = {};
  for (const a of results[i].json.activities ?? []) {
    if (!String(a.run_name).startsWith(c.label) || /\btest\b/i.test(a.run_name)) continue;
    const day = a.started_at ? DateTime.fromISO(a.started_at).setZone(c.timezone).toISODate() : 'unknown';
    const d = days[day] ??= { total: 0, first_attempts: 0, retries: 0, connected: 0, successes: 0, outcomes: {}, success_contacts: [] };
    const o = String(a.outcome ?? 'failed').toLowerCase();
    d.total++;
    /\(Retry \d+\)/.test(a.run_name) ? d.retries++ : d.first_attempts++;
    if (!notConnected.has(o)) d.connected++;
    if (success.has(o)) { d.successes++; d.success_contacts.push(String(a.contact_id)); }
    const key = o.replace(/\s+/g, '_');
    d.outcomes[key] = (d.outcomes[key] ?? 0) + 1;
  }
  for (const [date, d] of Object.entries(days)) rows.push({ campaign_key: plan.campaign_key, date, ...d });
});
return rows.sort((a, b) => a.date.localeCompare(b.date)).map(r => ({ json: r }));

// Optional: check whether successes actually materialised (e.g. booked → attended) on the CRM record.
const cfg = $('Load config').first().json;
const want = new Map();
for (const { json: r } of $('Build daily rows').all()) {
  const field = cfg.campaigns[r.campaign_key].kpi?.realization?.field;
  if (field) for (const id of r.success_contacts) want.set(id, field);
}
if (!want.size) return [{ json: { op: 'noop', payload: {} } }];
return [...want.entries()].map(([id, field]) => ({ json: { op: 'get_record', payload: { id, fields: [field] }, _id: id } }));

const cfg = $('Load config').first().json;
const lookups = $('Build realization lookups').all();
const results = $input.all();
const realized = new Set();
lookups.forEach(({ json: l }, i) => {
  if (l.op !== 'get_record') return;
  const f = results[i]?.json?.fields ?? {};
  const [field] = l.payload.fields;
  const truthy = Object.values(cfg.campaigns).find(c => c.kpi?.realization?.field === field)?.kpi.realization.truthy ?? [];
  const v = f[field];
  if (truthy.includes(v) || (truthy.includes('non_empty') && v != null && v !== '')) realized.add(l._id);
});
const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 : 0);
return $('Build daily rows').all().map(({ json: r }) => {
  const hasRealization = !!cfg.campaigns[r.campaign_key].kpi?.realization;
  const realizedCount = hasRealization ? r.success_contacts.filter(id => realized.has(id)).length : null;
  const { success_contacts, ...row } = r;
  return { json: {
    ...row,
    realized: realizedCount,
    connect_rate_pct: pct(r.connected, r.total),
    success_rate_pct: pct(r.successes, r.connected),
    realization_rate_pct: hasRealization ? pct(realizedCount, r.successes) : null,
    generated_at: DateTime.now().toUTC().toISO(),
  } };
});
